#include <bits/stdc++.h>
using namespace std;

int main() {
    string s;
    getline(cin, s);
    auto starts_with = [](const string& str, const string& prefix) {
        return str.size() >= prefix.size() && str.compare(0, prefix.size(), prefix) == 0;
    };
    auto ends_with = [](const string& str, const string& suffix) {
        return str.size() >= suffix.size() && str.compare(str.size() - suffix.size(), suffix.size(), suffix) == 0;
    };

    bool condition = false;
    if (starts_with(s, "dot") || starts_with(s, "at") ||
        (s.size() >= 2 && ends_with(s, "at")) ||
        (s.size() >= 3 && ends_with(s, "dot"))) {
        condition = true;
    }

    if (condition) {
        if (starts_with(s, "dot")) {
            string t = s.substr(3);
            vector<string> a;
            size_t pos = 0;
            while ((pos = t.find("dot")) != string::npos) {
                a.push_back(t.substr(0, pos));
                t.erase(0, pos + 3);
            }
            a.push_back(t);
            string l = "";
            for (size_t i = 0; i < a.size(); ++i) {
                l += a[i];
                if (i != a.size() - 1) l += ".";
            }
            size_t b = l.find("at");
            string o = l.substr(0, b) + "@" + l.substr(b + 2);
            string q = "dot" + o;
            if (!q.empty() && q.back() == '.') {
                string a_str = q.substr(0, q.size() - 1);
                s = a_str + "dot";
            } else if (!q.empty() && q.back() == '@') {
                string a_str = q.substr(0, q.size() - 1);
                s = a_str + "at";
            } else {
                s = q;
            }
        }

        if (starts_with(s, "at")) {
            string t = s.substr(2);
            vector<string> a;
            size_t pos = 0;
            while ((pos = t.find("dot")) != string::npos) {
                a.push_back(t.substr(0, pos));
                t.erase(0, pos + 3);
            }
            a.push_back(t);
            string l = "";
            for (size_t i = 0; i < a.size(); ++i) {
                l += a[i];
                if (i != a.size() - 1) l += ".";
            }
            size_t b = l.find("at");
            string o = l.substr(0, b) + "@" + l.substr(b + 2);
            string q = "at" + o;
            if (!q.empty() && q.back() == '.') {
                string a_str = q.substr(0, q.size() - 1);
                s = a_str + "dot";
            } else if (!q.empty() && q.back() == '@') {
                string a_str = q.substr(0, q.size() - 1);
                s = a_str + "at";
            } else {
                s = q;
            }
        }

        if (s.size() >= 3 && ends_with(s, "dot") && !starts_with(s, "dot") && !starts_with(s, "at")) {
            string t = s.substr(0, s.size() - 3);
            vector<string> a;
            size_t pos = 0;
            while ((pos = t.find("dot")) != string::npos) {
                a.push_back(t.substr(0, pos));
                t.erase(0, pos + 3);
            }
            a.push_back(t);
            string l = "";
            for (size_t i = 0; i < a.size(); ++i) {
                l += a[i];
                if (i != a.size() - 1) l += ".";
            }
            size_t b = l.find("at");
            string o = l.substr(0, b) + "@" + l.substr(b + 2);
            s = o + "dot";
        }

        if (s.size() >= 2 && ends_with(s, "at") && !starts_with(s, "dot") && !starts_with(s, "at")) {
            string t = s.substr(0, s.size() - 2);
            vector<string> a;
            size_t pos = 0;
            while ((pos = t.find("dot")) != string::npos) {
                a.push_back(t.substr(0, pos));
                t.erase(0, pos + 3);
            }
            a.push_back(t);
            string l = "";
            for (size_t i = 0; i < a.size(); ++i) {
                l += a[i];
                if (i != a.size() - 1) l += ".";
            }
            size_t b = l.find("at");
            string o = l.substr(0, b) + "@" + l.substr(b + 2);
            s = o + "at";
        }

        cout << s << "\n";

    } else {
        vector<string> a;
        size_t pos = 0;
        string t = s;
        while ((pos = t.find("dot")) != string::npos) {
            a.push_back(t.substr(0, pos));
            t.erase(0, pos + 3);
        }
        a.push_back(t);
        string l = "";
        for (size_t i = 0; i < a.size(); ++i) {
            l += a[i];
            if (i != a.size() - 1) l += ".";
        }
        size_t b = l.find("at");
        string q = l.substr(0, b) + "@" + l.substr(b + 2);
        cout << q << "\n";
    }
    return 0;
}

